/**
 * Generate `.svelte-kit/tsconfig.json` if it is not there yet.
 *
 * `tsconfig.scripts.json` extends `tsconfig.json`, which extends `./.svelte-kit/tsconfig.json` — and
 * that last file is GENERATED by `svelte-kit sync`, so it is gitignored and absent until something
 * runs `dev` or `build`. Every check running under the scripts tsconfig therefore dies with
 * `Error: File './.svelte-kit/tsconfig.json' not found.` in a checkout that has done neither: a
 * fresh clone, or — far more often — a new git worktree. Four of the six launcher checks failed
 * that way and read as broken code rather than a missing generated file.
 *
 * `pnpm install` now writes the file (the package's `prepare` runs `svelte-kit sync`, as SvelteKit's
 * own template does), so a single `pnpm --filter launcher-api check:<x>` works in any installed
 * checkout. `scripts/check-all.mjs` still runs this once before its parallel checks, for a checkout
 * where it is missing anyway. If a lone check dies with the error above, run `pnpm install` (or
 * `svelte-kit sync` in apps/launcher-api).
 *
 * Guarded rather than unconditional because `sync` costs ~3s, and the file is usually there.
 */
import { existsSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const pkgRoot = fileURLToPath(new URL('..', import.meta.url));

if (existsSync(new URL('../.svelte-kit/tsconfig.json', import.meta.url))) process.exit(0);

console.log('.svelte-kit/tsconfig.json is missing — running `svelte-kit sync` first…');
// `node_modules/.bin` is on PATH because this runs as a pnpm script; `shell` resolves the Windows
// `.CMD` shim that a bare spawn would miss.
const { status, error } = spawnSync('svelte-kit', ['sync'], {
	cwd: pkgRoot,
	stdio: 'inherit',
	shell: true,
});

if (error) {
	console.error(`could not run \`svelte-kit sync\`: ${error.message}`);
	process.exit(1);
}
process.exit(status ?? 1);
